groups: {
  billing: {tables: [&: refer(), path($.invoice), path($.payment)], procs: [&: refer(), path($.charge)]}
  identity: {tables: [&: refer(), path($.customer)]}
  empty: {note: "none"}
}
customer: {domain: identity, kind: table, columns: {id: integer & min(1), name: string, tags: [string], "first name": string}}
invoice: {domain: billing, kind: table, columns: {id: integer, customer: refer() & path($.customer), total: number, status: "open" | "paid"}, refs: [&: refer(), path($.customer)]}
payment: {domain: billing, kind: table, columns: {id: integer, invoice: refer() & path($.invoice), meta: {}}, refs: [&: refer(), path($.invoice)]}
charge: {domain: billing, kind: process, refs: [&: refer(), path($.payment)]}

